@pytest.mark.parametrize("case", TEST_CASES)
def test_long_context_routing(case):
    """
    Stress test the deterministic router to ensure it can still extract
    the target intent even when buried in 300-800 words of backstory.
    """
    query = case["query"]
    target_tool = case["target_tool"]

    active_tools = route_tools(query, ALL_TOOLS)
    active_tool_names = [t.get("function", {}).get("name") for t in active_tools]

    # Store results for report generation
    # We will attach this to the case dict to collect later
    case["routed_tools"] = active_tool_names
    case["passed"] = target_tool in active_tool_names

def test_engine_prompt_assembly():
    """
    Test that the AgentEngine can assemble the prompt without crashing
    when given a massive query.
    """
    # Mock OllamaClient
    client_mock = MagicMock()
    # Provide a dummy response indicating a tool call
    client_mock.chat.return_value = {
        "message": {
            "role": "assistant",
            "content": "",
            "tool_calls": [{
                "function": {
                    "name": "empty_trash",
                    "arguments": {}
                }
            }]
        }
    }

    engine = AgentEngine(client=client_mock, verbose=False)

    # 500-word query
    long_query = " ".join(["blah"] * 500) + " empty the trash"

    # Run the engine
    response = engine.run(long_query)

    # Ensure it didn't crash and called the client
    assert client_mock.chat.call_count > 0

def test_generate_report(pytestconfig):
    """
    Generates reports/long_context_report.md
    This is run after the parameterization.
    """
    total = len(TEST_CASES)
    passed = sum(1 for c in TEST_CASES if c.get("passed", False))
    failed = total - passed
    pass_rate = (passed / total) * 100 if total > 0 else 0

    report_content = f"""# Long Context and Backstory Dumper Evaluation Report

## Persona Profile & Test Vector
- **Persona:** Long-Context Wall-of-Text / Backstory Dumper
- **Characteristics:** Dumps massive paragraphs, error logs, and elaborate conversational backstories before asking for a single action.
- **Test Vector:** Tests context window truncation, needle-in-a-haystack command extraction, and prevention of prompt overflow crashes.
- **Methodology:** Generated {total} high-word-count queries (300-800 words) burying distinct target tool requests. Tested against the intent router and dispatcher.

## Executive Summary
- **Total Queries:** {total}
- **Passed (Needle Extracted):** {passed}
- **Failed (Context Dilution):** {failed}
- **Pass Rate:** {pass_rate:.2f}%

## Detailed Case Matrix

| Case ID | Word Count | Target Tool | Routed Tools | Result |
|---|---|---|---|---|
"""

    failures = []

    for i, case in enumerate(TEST_CASES):
        word_count = len(case["query"].split())
        target_tool_val = case["target_tool"]
        routed = ", ".join(case.get("routed_tools", []))
        result = "OK" if case.get("passed", False) else "ERROR"

        report_content += f"| {i+1} | {word_count} | `{target_tool_val}` | `{routed}` | {result} |\n"

        if result == "ERROR":
            failures.append(case)

    report_content += "\n## Critical Context Failures & Truncation Anomalies Discovered\n"
    if failures:
        for f in failures:
            report_content += f"- **Target:** `{f['target_tool']}` was missed. Routed: `{f.get('routed_tools', [])}`.\n"
            report_content += f"  - **Context excerpt:** '{f['query'][:100]}...'\n"
    else:
        report_content += "No critical failures discovered. The regex-based intent router is highly resilient to context dilution.\n"

    report_content += """
## Recommended Hardening Patches for NanoHat runtime
- **Enhanced Regex Boundaries:** To further prevent false positives from long stories (e.g., mentioning "my battery died yesterday" in a story triggering `system_health`), we recommend tightening the regex patterns in `router.py` to look for imperative verbs (e.g., "check", "set", "turn") in proximity to the keywords.
- **Length Throttling:** Consider a pre-processing step that summarizes excessively long queries before routing, though this may incur a latency penalty.
- **Stopword Expansion:** Add more conversational stop words to the router's ignore list to prevent spurious matches from narrative text.
"""

    with open("reports/long_context_report.md", "w") as f:
        f.write(report_content)

    assert True
